import base64,hashlib,json,os,pathlib,subprocess,time
observed=subprocess.run(['nvidia-smi','--query-gpu=uuid','--format=csv,noheader'],capture_output=True,text=True,check=True).stdout.splitlines()
assert [line.strip() for line in observed if line.strip()]==[INPUT['expected_GPU_UUID']]
root=pathlib.Path(INPUT['remote_repo'])/INPUT['remote_phase']/INPUT['execution_folder']
assert not (root/'START_GUARD.json').exists(), 'Existing launch guard: do not stage or relaunch'
for record in RECORDS:
 path=root/record['relative_path']; payload=base64.b64decode(record['base64'])
 assert len(payload)==record['bytes'] and hashlib.sha256(payload).hexdigest()==record['sha256']
 if path.exists():
  current=path.read_bytes()
  assert len(current)==record['bytes'] and hashlib.sha256(current).hexdigest()==record['sha256'], 'Refuse different existing file: '+str(path)
config_bytes=(json.dumps(INPUT,indent=2)+'\n').encode()
config_path=root/'EXECUTION_INPUT.json'
if config_path.exists(): assert config_path.read_bytes()==config_bytes, 'Refuse different execution input'
root.mkdir(parents=True,exist_ok=True)
new=0
for record in RECORDS:
 path=root/record['relative_path']
 if not path.exists():
  path.parent.mkdir(parents=True,exist_ok=True)
  with path.open('xb') as stream: stream.write(base64.b64decode(record['base64']))
  path.chmod(int(record['mode'],8));new+=1
if not config_path.exists():
 with config_path.open('xb') as stream: stream.write(config_bytes)
(root/'tmp').mkdir(mode=0o700,exist_ok=True)
receipt=dict(staged_unix=time.time(),GPU_UUID=INPUT['expected_GPU_UUID'],staged_files=len(RECORDS),new_files=new,all_hashes_verified=True,no_differing_files_overwritten=True,execution_root=str(root),harness_manifest_sha256=INPUT['harness_manifest_sha256'])
with (root/'STAGING_RECEIPT.json').open('x') as stream: json.dump(receipt,stream,indent=2);stream.write('\n')
print(json.dumps(receipt))
